public Double sumPrice(BOM_D children){
 Double sun = 0D;
 if (children.getIsLeaf()){
 List<BOM_D> d = children.getD();
 for (BOM_D bom_d : d) {
 sun+=sumPrice(bom_d);
 }
 }else {
 String priceTC = children.getPriceTC();
 if (!StringUtils.isEmpty(priceTC)){
 sun+=Double.parseDouble(priceTC);
 }
 }
 String format = decimalFormat.format(sun);
 children.setPriceTC(format);

